public class DeferredRunner {interface Task{Object run();}static void run(String name,int mode,Task t){DeferredSupport.trace=0;DeferredSupport.mode=mode;DeferredSupport.field=5;DeferredSupport.shared=new int[]{7};try{System.out.println(name+mode+":"+t.run()+":"+DeferredSupport.trace);}catch(RuntimeException e){System.out.println(name+mode+":"+e.getClass().getName()+":"+(e==DeferredSupport.FAILURE)+":"+DeferredSupport.trace);}}public static void main(String[]a){for(int m=0;m<3;m++){run("call",m,()->DeferredValues.call());run("field",m,()->DeferredValues.field());run("array",m,()->DeferredValues.array(DeferredSupport.shared));run("nullArray",m,()->DeferredValues.array(null));run("goodCast",m,()->DeferredValues.cast("yes"));run("badCast",m,()->DeferredValues.cast(new Object()));}}}
